def about():return banner('ABOUT US','懂金融，更懂上海。','沪上银专注为上海本地企业与个人提供融资咨询、资料梳理与方案匹配建议。')+'''<section class="section shell narrow-copy"><div class="eyebrow dark">OUR PHILOSOPHY</div><h2>先理解资金问题，<br>再讨论融资方案。</h2><p>我们相信，融资不只是“能否贷到钱”，更关系到企业的经营节奏、现金流安全和未来还款能力。沪上银以本地化服务、专业化分析与透明沟通为核心，帮助客户理解融资路径与风险边界。</p><p>对于不适合立即申请的情况，我们同样建议先优化经营与信用条件，而不是反复提交申请。</p></section><section class="section soft"><div class="shell"><div class="grid triptych"><div class="principle"><span>01</span><h3>本地化深度</h3><p>围绕上海本地经营环境与客户需求，提供有针对性的沟通。</p></div><div class="principle"><span>02</span><h3>数据化判断</h3><p>从征信、流水、财务和负债入手，基于事实评估适配情况。</p></div><div class="principle"><span>03</span><h3>透明化服务</h3><p>清楚沟通服务内容、收费规则、方案局限及可能风险。</p></div></div></div></section>'''+cta()

def services(kind):
 ent=kind=='enterprise'; names=('企业融资服务','个人融资服务'); title=names[0 if ent else 1]; desc='面向中小微企业、个体工商户及经营主体，围绕经营活动、现金流和融资用途制定合理规划。' if ent else '围绕收入、征信、负债与资金用途，协助个人客户理解适合的融资路径及风险。'; rows=[PRODUCTS[i] for i in ([0,1,3,4] if ent else [2,1])]; fs=[('申请前应先看哪些材料？','常见包括营业执照、征信、流水、纳税与财务资料，具体以金融机构要求为准。'),('企业成立时间短可以申请吗？','部分产品有经营年限要求。应结合实际经营记录与产品准入标准进行判断。')] if ent else [('个人信用贷一定不需要担保吗？','不同产品担保方式有所差异，具体以金融机构提供的合同与条件为准。'),('收入不稳定可以申请吗？','需要审慎评估收入持续性与每月偿债压力，并非所有客户都适合新增贷款。')]
 return banner('FINANCING SERVICES',title,desc)+'''<section class="section shell"><div class="section-head"><div><div class="eyebrow dark">SERVICE SOLUTIONS</div><h2>根据条件，选择路径。</h2></div><p>所有方案均需评估资金用途、征信记录与还款来源，不能仅凭单一资质判断是否可申请。</p></div>'''+product_cards(rows)+'''</section><section class="section soft"><div class="shell"><div class="section-head"><div><div class="eyebrow dark">PREPARATION</div><h2>申请前，建议先准备。</h2></div></div><div class="content-panel">'''+bullets(['真实、可核验的身份及经营资料','近期征信记录及现有负债明细','收入、经营流水与实际还款来源证明','资金用途说明及相关合同材料','充分理解利率、费用、期限和违约风险'])+'''</div></div></section><section class="section shell"><div class="section-head"><div><div class="eyebrow dark">FAQ</div><h2>常见问题。</h2></div></div>'''+faq(fs)+'''</section>'''+cta()

def products():
 return banner('OUR SOLUTIONS','融资产品与服务方案','根据真实经营、信用和偿债能力选择适合的融资方向，而非追求单一额度或低价宣传。')+'''<section class="section shell"><div class="filter-row" role="group" aria-label="产品分类筛选"><button class="filter-chip active" data-filter="all">全部方案</button><button class="filter-chip" data-filter="企业">企业融资</button><button class="filter-chip" data-filter="抵押">抵押融资</button><button class="filter-chip" data-filter="个人">个人融资</button><button class="filter-chip" data-filter="服务">配套服务</button></div><div class="product-details">'''+''.join(f'<article class="detail-card" id="product-{i+1}" data-category="{esc(p[1])}"><div class="detail-index">0{i+1} / SOLUTION</div><div><span class="mini-tag">{esc(p[1])}</span><h2>{esc(p[0])}</h2><p>{esc(p[3])}</p><div class="detail-spec"><div><b>评估重点</b><p>{esc(p[4])}</p></div><div><b>建议资料</b><p>{esc(p[5])}</p></div></div><p class="quiet">具体额度、利率、期限及申请条件由贷款机构根据实际情况确定。</p><a href="/contact/" class="button navy">咨询这一方案 ↗</a></div></article>' for i,p in enumerate(PRODUCTS))+'''</div></section>'''+risk_strip()+cta()

def precheck():return banner('DOCUMENT REVIEW','资料预审 · 先判断，再行动。','先准备关键信息，识别潜在风险，减少盲目申请。本演示站暂不接收征信等敏感文件。')+'''<section class="section shell"><div class="section-head"><div><div class="eyebrow dark">PRE-CHECK PROCESS</div><h2>四步完成资料准备。</h2></div></div><div class="grid triptych four">'''+''.join(f'<div class="principle"><span>0{i+1}</span><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate([('基础信息','描述需求与申请主体'),('核对清单','按产品准备真实材料'),('安全提交','正式开通安全通道后上传'),('评估沟通','获得适配与风险建议')]))+'''</div><div class="review-layout"><div><div class="eyebrow dark">REQUIRED DOCUMENTS</div><h2>常见资料清单</h2>'''+bullets(['营业执照及经营主体信息（企业）','身份证明及必要的授权材料','征信报告（须经授权并通过安全渠道提交）','近期开票、纳税、银行流水（按产品要求）','财报、经营合同与房产权属证明（适用时）'])+'''<div class="notice"><b>隐私保护</b><p>征信报告、银行流水等可能包含敏感个人信息。正式上线前必须完成加密传输、权限隔离、保存期限及删除机制等安全措施。</p></div></div><div class="upload-demo"><span class="mini-tag">FILE PREVIEW · DEMO</span><h3>资料清单自检</h3><p>这里可以选择文件检查格式与大小，但不会上传到服务器，也不会进行实际评估。</p><label class="fake-upload" for="document-files"><span class="upload-icon">⇧</span><b>选择资料文件（仅本地检查）</b><small>支持 JPG、PNG、PDF，单个文件不超过 10MB</small></label><input id="document-files" type="file" accept=".jpg,.jpeg,.png,.pdf" multiple hidden><div id="file-feedback" class="file-feedback" aria-live="polite">尚未选择文件</div><a class="button navy full" href="/contact/">咨询安全资料提交方式 ↗</a><p class="form-note">目前未开通上传服务，不会保存您的资料或生成授信结论。</p></div></div></section>'''+cta()

def cases():return banner('CASE SCENARIOS','融资案例场景','了解不同经营情况的规划思路。以下均为模拟情景，不代表沪上银实际服务业绩或银行审批结果。')+'''<section class="section shell"><div class="notice case-notice"><b>案例真实性说明</b><p>PRD提供的案例是虚拟示例。为避免误导，本站统一展示为“模拟案例场景”，不使用“成功获批”等未经核实的表述。</p></div>'''+case_cards()+'''</section>'''+cta()

def risks():return banner('DISCLOSURES','风险提示与免责声明','金融决策需要充分了解成本、责任和不确定性。请在申请贷款前认真阅读。')+'''<section class="section shell"><div class="risk-content"><h2>请您特别注意</h2>'''+bullets(['本站提供贷款信息咨询与资料梳理建议，不是银行或贷款发放机构。','贷款是否批准、实际额度、利率、期限、担保方式以金融机构审核和合同为准。','不承诺“包过”“百分百放款”或任何形式的审批保证。','不收取违规前置费用；任何服务收费应在合法合规前提下明示并取得确认。','不得提交虚假流水、虚假合同或其他不实资料。'])+'''<h2>可能遇到的融资风险</h2><div class="grid two-cols"><div class="info-box"><h3>征信风险</h3><p>逾期、较高频次的信贷查询等记录可能影响审核，应谨慎申请。</p></div><div class="info-box"><h3>负债与还款风险</h3><p>贷款增加债务负担，现金流不足可能导致逾期和额外费用。</p></div><div class="info-box"><h3>经营与抵押风险</h3><p>经营变化、诉讼、资产处置限制等可能影响贷款资格；抵押贷款可能面临抵押物处置风险。</p></div><div class="info-box"><h3>个人信息与诈骗风险</h3><p>注意识别冒名收费、虚假贷款广告，勿随意向不明主体发送征信及身份证资料。</p></div></div><h2>服务边界</h2><p>沪上银提供咨询及资料整理等辅助服务，金融机构独立进行调查、审批、合同签署及放款。网站内容仅供一般信息参考，不构成金融机构授信承诺或个性化财务/法律建议。</p></div></section>'''+cta()

def contact():return banner('CONTACT US','聊聊您的融资需求。','告诉我们您的基本情况，从问题诊断开始，而不是盲目寻找贷款。')+'''<section class="section shell"><div class="contact-layout"><div><div class="eyebrow dark">GET IN TOUCH</div><h2>以专业，回应每一次信任。</h2><p class="lead">服务区域：上海及周边地区。正式联系电话、企业微信和办公地点将在资料核验后开放展示。</p><div class="contact-info"><div><span>01 / 服务内容</span><b>融资咨询 · 资料梳理 · 风险初评</b></div><div><span>02 / 服务区域</span><b>上海及周边地区</b></div><div><span>03 / 联系方式</span><b>待配置真实电话及企业微信</b></div></div><div class="notice"><b>当前为网站演示版</b><p>为保护个人信息，咨询表单暂未连接后台，请勿填写真实敏感资料。部署前需配置正式联系方式与安全接收接口。</p></div></div><div><div class="form-intro"><h3>预约融资咨询</h3><p>填写基本信息，查看表单交互演示。</p></div>'''+contact_form()+'''</div></div></section>'''

def insights():return banner('FINANCING INSIGHTS','沪上银 · 融资知识库','围绕上海企业融资、征信管理与现金流规划，持续解答真实的融资问题。')+'''<section class="section shell"><div class="grid article-grid">'''+''.join(f'<a class="article-card" href="/insights/{slug}/"><div class="article-top"><span>KNOWLEDGE / 0{i+1}</span><span>↗</span></div><span class="mini-tag">{esc(cat)}</span><h3>{esc(t)}</h3><p>{esc(d)}</p><span class="article-bottom">阅读完整文章 →</span></a>' for i,(slug,t,cat,d,qs) in enumerate(ARTICLES))+'''</div></section>'''+cta()

def privacy():return banner('PRIVACY','隐私政策','我们重视用户隐私。本页面说明当前演示版本的数据处理边界。')+'''<section class="section shell narrow-copy"><h2>当前演示站的数据处理</h2><p>本网站提供静态信息展示和本地表单交互演示。目前不启用服务端客户数据库，也不接收咨询表单内容或用户资料文件。表单数据仅在当前浏览器页面中暂时存在，页面刷新后不保留。</p><h2>正式上线前的要求</h2><p>正式开通咨询与预审服务前，我们将明确个人信息处理者身份、联系方式、处理目的、处理方式、保存期限、用户权利、撤回同意渠道，以及委托处理和第三方共享情况；并按实际业务流程设置必要的独立授权和安全措施。</p><p>本页面为上线前的占位政策，请勿在尚未完善公示信息及安全控制时向客户开放真实材料上传。</p></section>'''

def article(art):
 slug,title,cat,description,sections=art
 return banner(cat,title,description)+f'<article class="section shell editorial"><a class="back-link" href="/insights/">← 返回融资知识库</a><p class="editorial-lead">{esc(description)}</p>'+''.join(f'<section><h2>{esc(q)}</h2><p>{esc(a)}</p></section>' for q,a in sections)+'''<div class="notice"><b>提示</b><p>不同银行与产品要求可能变化。本文仅作知识普及，实际审批条件以金融机构规定为准。</p></div></article>'''+cta()

PAGES={'/':('沪上银｜上海企业与个人融资咨询及规划服务','上海本地企业经营贷、房抵经营贷、个人融资咨询，提供资料预审思路、融资方案匹配和风险提示。',home),'/about/':('关于沪上银｜上海本地融资咨询品牌','了解沪上银的融资服务理念与本地化专业咨询。',about),'/enterprise/':('上海企业融资咨询｜经营贷、流水贷与房抵经营贷','沪上银提供企业经营贷、流水贷、设备周转与房抵经营贷咨询与资料准备建议。',lambda:services('enterprise')),'/personal/':('上海个人融资咨询｜信用贷与房产抵押融资','了解上海个人信用贷、房产抵押融资等方案的适用条件及风险。',lambda:services('personal')),'/products/':('融资产品方案｜企业经营贷、房抵贷与信用贷','按企业、个人与抵押类型查看融资方案、常见材料和评估重点。',products),'/precheck/':('融资资料预审清单｜征信、流水与营业执照','融资申请前需要准备哪些资料？了解征信、企业经营流水、财务与房产资料的评估重点。',precheck),'/cases/':('融资案例场景｜上海企业经营周转与抵押融资','查看贸易、餐饮、软件企业等模拟融资需求场景，理解方案选择思路。',cases),'/risks/':('贷款风险提示｜征信、负债与审批风险说明','贷款审批以银行为准，了解征信、负债、抵押、资料真实性等风险及免责声明。',risks),'/contact/':('联系沪上银｜预约上海融资咨询','联系沪上银了解企业及个人融资咨询，预约初步需求沟通。',contact),'/insights/':('融资知识库｜上海企业融资、征信及现金流规划','沪上银融资知识库，系统解答企业经营贷、信用风险、经营现金流等常见问题。',insights),'/privacy/':('隐私政策｜沪上银','沪上银网站隐私政策及演示版个人信息处理说明。',privacy)}
for art in ARTICLES:PAGES['/insights/'+art[0]+'/']=(art[1]+'｜沪上银融资知识库',art[3],lambda a=art:article(a))

def structured(path,title,desc):
 org={'@type':'Organization','@id':SITE+'/#organization','name':'沪上银','url':SITE+'/','description':'上海本地企业与个人融资咨询服务品牌。','areaServed':{'@type':'Place','name':'上海'}}
 breadcrumb=[{'@type':'ListItem','position':1,'name':'首页','item':SITE+'/'}]
 if path!='/':breadcrumb.append({'@type':'ListItem','position':2,'name':title.split('｜')[0],'item':SITE+path})
 arr=[{'@context':'https://schema.org',**org},{'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':SITE+path,'inLanguage':'zh-CN','publisher':{'@id':SITE+'/#organization'}},{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':breadcrumb}]
 if path.startswith('/insights/') and path!='/insights/':arr.append({'@context':'https://schema.org','@type':'Article','headline':title.split('｜')[0],'description':desc,'inLanguage':'zh-CN','author':{'@id':SITE+'/#organization'},'publisher':{'@id':SITE+'/#organization'},'mainEntityOfPage':SITE+path})
 return '<script type="application/ld+json">'+json.dumps(arr,ensure_ascii=False).replace('<','\\u003c')+'</script>'

def document(path,title,desc,body):return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0A1628"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="index,follow"><link rel="canonical" href="{SITE+path}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/style.css"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{SITE+path}">{structured(path,title,desc)}</head><body>{header(path)}<main id="main">{body}</main>{footer()}<script defer src="/assets/navigation.js"></script><script defer src="/assets/site.js"></script></body></html>'''
for path,(title,desc,func) in PAGES.items():
 out=P/path.lstrip('/')/'index.html' if path!='/' else P/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(document(path,title,desc,func()),encoding='utf-8')
(P/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+SITE+'/sitemap.xml\n',encoding='utf-8')
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{SITE+u}</loc><changefreq>{"monthly" if "/insights/" in u else "weekly"}</changefreq></url>' for u in PAGES)+'</urlset>',encoding='utf-8')
print('Generated',len(PAGES),'pages')
